func TestPR137AbsoluteAliasMustNotCollapseUntraversableParent(t *testing.T) {
	repo := t.TempDir()
	victim := filepath.Join(repo, "victim.md")
	before := []byte("PRECIOUS\n")
	if err := os.WriteFile(victim, before, 0o644); err != nil {
		t.Fatal(err)
	}
	target := strings.Join([]string{repo, "missing", "..", "victim.md"}, string(filepath.Separator))
	if err := os.Symlink(target, filepath.Join(repo, "AGENTS.md")); err != nil {
		t.Fatal(err)
	}
	if _, err := os.OpenFile(filepath.Join(repo, "AGENTS.md"), os.O_WRONLY|os.O_CREATE, 0o644); err == nil {
