			symlinkForTest(t, filepath.Join(docsAlias, "shared.md"), filepath.Join(repo, "AGENTS.md"))

			runInitAgentsForTest(t, repo)

			if got := readFileForTest(t, shared); !strings.Contains(got, testAgentPointerBlock) {
