//go:build windows

package cli

import (
	"encoding/binary"
	"fmt"
	"os"
	"path/filepath"
	"syscall"
)

// windowsLinkRequiresDirectory returns the type encoded into a Windows symbolic link or
// name-surrogate reparse point. Windows preserves this bit independently of the current target;
// a directory link cannot be followed after its target is replaced by a regular file, and vice
// versa.
func windowsLinkRequiresDirectory(info os.FileInfo) (bool, bool) {
	data, ok := info.Sys().(*syscall.Win32FileAttributeData)
	if !ok {
		return false, false
	}
	return data.FileAttributes&syscall.FILE_ATTRIBUTE_DIRECTORY != 0, true
}

// windowsRawSymlinkPrintName reads the spelling CreateSymbolicLink stored in the reparse point.
// os.Root.Readlink deliberately normalizes an absolute NT substitute name such as
// `\??\C:\path` to `C:\path`; that loses whether the caller used the `\\?\` namespace, whose
// dot, separator, and trailing-space rules cannot be represented by the confined relative path
// used after containment translation.
func windowsRawSymlinkPrintName(rootPath, name string, expected os.FileInfo) (string, bool, error) {
	fullPath := filepath.Join(rootPath, name)
	path, err := syscall.UTF16PtrFromString(fullPath)
	if err != nil {
		return "", false, err
	}
	handle, err := syscall.CreateFile(
		path,
		0,
		syscall.FILE_SHARE_READ|syscall.FILE_SHARE_WRITE|syscall.FILE_SHARE_DELETE,
		nil,
		syscall.OPEN_EXISTING,
		syscall.FILE_FLAG_BACKUP_SEMANTICS|syscall.FILE_FLAG_OPEN_REPARSE_POINT,
		0,
	)
	if err != nil {
		return "", false, err
	}
	file := os.NewFile(uintptr(handle), fullPath)
	if file == nil {
		syscall.CloseHandle(handle)
		return "", false, fmt.Errorf("open raw Windows symlink target: invalid handle")
	}
	defer file.Close()
	opened, err := file.Stat()
	if err != nil {
		return "", false, err
	}
	if !os.SameFile(expected, opened) {
		return "", false, fmt.Errorf("Windows symlink changed while its target was inspected")
	}

	buffer := make([]byte, syscall.MAXIMUM_REPARSE_DATA_BUFFER_SIZE)
	var returned uint32
	if err := syscall.DeviceIoControl(
		handle,
		syscall.FSCTL_GET_REPARSE_POINT,
		nil,
		0,
		&buffer[0],
		uint32(len(buffer)),
		&returned,
		nil,
	); err != nil {
		return "", false, err
	}
	if returned < 20 || binary.LittleEndian.Uint32(buffer[:4]) != syscall.IO_REPARSE_TAG_SYMLINK {
		return "", false, nil
	}

	// REPARSE_DATA_BUFFER's 8-byte header is followed by the symbolic-link
	// offsets/lengths and flags (12 bytes), then its UTF-16 path buffer.
	printOffset := int(binary.LittleEndian.Uint16(buffer[12:14]))
	printLength := int(binary.LittleEndian.Uint16(buffer[14:16]))
	pathStart := 20 + printOffset
	pathEnd := pathStart + printLength
	if printLength == 0 || printLength%2 != 0 || pathStart < 20 || pathEnd > int(returned) {
		return "", false, nil
	}
	printName := make([]uint16, printLength/2)
	for i := range printName {
		start := pathStart + 2*i
		printName[i] = binary.LittleEndian.Uint16(buffer[start : start+2])
	}
	return syscall.UTF16ToString(printName), true, nil
}

